def _get(name: str) -> List[float]:
    for n, v in EXPECTED:
        if n == name:
            return v
    raise ValueError("missing " + name)

def check(name: str, got, rtol: float = 1e-7, atol: float = 1e-10):
    want = _get(name)
    g = List[float]()
    for v in got:
        if isinstance(v, np.ndarray):
            for w in v.ravel():
                g.append(float(w))
        else:
            g.append(float(v))
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g, want)

rng = np.random.RandomState(0)
X = rng.randn(80, 4)
yb = np.empty(80, dtype=int)
y3 = np.empty(80, dtype=int)
for i in range(80):
    d = X[i, 0] - X[i, 1] + 0.5 * X[i, 2] + 0.5 * rng.randn()
    yb[i] = 1 if d > 0 else 0
    y3[i] = 0 if d < -0.6 else (1 if d < 0.6 else 2)
sw = rng.uniform(0.5, 2.0, 80)

def cat(*parts) -> List[float]:
    r = List[float]()
    for p in parts:
        if isinstance(p, np.ndarray):
            for v in p.ravel():
                r.append(float(v))
        else:
            r.append(float(p))
    return r

def lr(name: str, m):
    check(name, cat(m.coef_, m.intercept_, m.n_iter_), 1e-8, 1e-11)

